#include "dve/editor_native.hpp"
#include "dve/editor_prefab.hpp"
#include <filesystem>
#include <iostream>
#include <stdexcept>
using namespace dve;using namespace dve::editor;
namespace {
void check(bool ok,const std::string& message){if(!ok)throw std::runtime_error(message);}
void fixture(EditorDocument& d){for(unsigned id=1;id<=3;++id){auto s=make_nurbs_patch(2);for(auto& p:s.controls){p.x+=2*(id-1);p.y=.03*p.z*p.z;}auto o=make_editor_nurbs(id,s);check(bool(o),"Reuse fixture");d.add_object(std::move(*o));}for(unsigned i=1;i<3;++i){auto r=link_nurbs_seam_command(i,i+1,{NurbsBoundary::UMax,NurbsBoundary::UMin,false,true})->execute(d);check(r.success,r.message);}}
void coherent(const EditorDocument& d){std::string error;check(d.validate(&error),error);}
auto hashes(const EditorDocument& d){std::vector<std::uint64_t> out;for(unsigned id=1;id<=3;++id)out.push_back(d.find_object(id)->polygon->contentHash);return out;}
void commands(){EditorDocument d("Network reuse");fixture(d);auto original=hashes(d);std::vector<ObjectTransformChange> changes;for(unsigned id=1;id<=3;++id){auto before=d.find_object(id)->transform,after=before;after.position={1,2,3};after.rotation=quaternion_from_axis_angle({0,1,0},.2F);changes.push_back({id,before,after});}TransformObjectsCommand move(changes);check(move.execute(d).success,"Whole network move/rotate");coherent(d);check(hashes(d)==original,"Placement preserves local display caches");check(move.undo(d).success,"Placement undo");
    TransformObjectsCommand partial({changes[0]});check(!partial.execute(d).success&&hashes(d)==original,"Partial network transform refuses");auto divergent=changes;divergent[2].after.position.x+=1;TransformObjectsCommand mismatch(divergent);check(!mismatch.execute(d).success&&d.find_object(1)->transform.position.x==0,"Divergent target frames refuse before mutation");
    std::vector<ObjectVoxelSizeChange> sizes;for(unsigned id=1;id<=3;++id){auto* o=d.find_object(id);sizes.push_back({id,o->transform,o->transform,o->voxelSizeMeters,o->voxelSizeMeters,o->voxelScale,Float3{2,3,.5F}});}ScaleVoxelSizeCommand scale(sizes);check(scale.execute(d).success,"Whole network anisotropic scale");coherent(d);check(scale.undo(d).success,"Scale undo");
    EditorObject group(90,"Network group");d.add_object(std::move(group));std::vector<ObjectReparentChange> parents;for(unsigned id=1;id<=3;++id)parents.push_back({id,{},90});ReparentObjectsCommand reparent(parents);check(reparent.execute(d).success,"Whole network grouping");coherent(d);check(reparent.undo(d).success,"Grouping undo");
    std::map<EditorObjectId,EditorObjectId> ids{{1,12},{2,10},{3,11}};std::vector<EditorObject> copies;for(unsigned id=1;id<=3;++id){auto copy=clone_editor_object(*d.find_object(id));copy.id=ids.at(id);copy.transform.position={4,1,2};std::string error;check(remap_nurbs_seam_ids(copy,id,ids,&error),error);copies.push_back(std::move(copy));}auto add=add_nurbs_network_objects_command(std::move(copies),"Copy network");check(add->execute(d).success,"Atomic remapped add");coherent(d);check(nurbs_seam_network_ids(d,10)==std::vector<EditorObjectId>({10,11,12})&&hashes(d)==original,"Copies only reference copies and leave originals unchanged");check(add->undo(d).success&&!d.find_object(10)&&add->execute(d).success,"Atomic copy undo/redo");coherent(d);
    auto copy=clone_editor_object(*d.find_object(1));copy.id=100;std::string error;check(!remap_nurbs_seam_ids(copy,1,{{1,100}},&error),"Partial ID remap refuses");
}
void native(){auto owner=std::make_unique<NativeEditorController>(EditorWorkspace(EditorDocument("Native reuse")));auto& c=*owner;c.resize(1600,1000);fixture(c.workspace().document());c.workspace().select_object(1);check(!c.dispatch_action("edit.copy")&&!c.dispatch_action("edit.duplicate"),"Native partial copy refuses");c.workspace().add_to_selection(2);c.workspace().add_to_selection(3);
    for(auto tool:{EditorToolId::Translate,EditorToolId::Rotate,EditorToolId::Scale}){c.set_active_tool(tool);auto axes=c.gizmo_axes();check(axes.size()==3,"Network object gizmo");auto axis=axes[tool==EditorToolId::Rotate?1:0];c.pointer_down(PointerButton::Primary,int(axis.end.x),int(axis.end.y),0);check(c.gizmo_dragging(),c.status().text);for(char ch:std::string(tool==EditorToolId::Scale?"1.2":tool==EditorToolId::Rotate?"5":"0.1"))c.key_down(std::string(1,ch),false,false,false);c.key_down("enter",false,false,false);check(!c.gizmo_dragging(),"Object placement finishes");coherent(c.workspace().document());check(c.dispatch_action("edit.undo"),"Native placement undo");coherent(c.workspace().document());}
    check(c.dispatch_action("edit.group"),"Group whole network");coherent(c.workspace().document());
    c.set_active_tool(EditorToolId::Scale);auto groupAxis=c.gizmo_axes()[0];c.pointer_down(PointerButton::Primary,int(groupAxis.end.x),int(groupAxis.end.y),0);check(c.gizmo_dragging(),c.status().text);for(auto key:{"1",".","1"})c.key_down(key,false,false,false);c.key_down("enter",false,false,false);coherent(c.workspace().document());check(c.dispatch_action("edit.undo"),"Group scale undo");check(c.dispatch_action("edit.undo"),"Group creation undo");coherent(c.workspace().document());
    c.workspace().select_object(1);c.workspace().add_to_selection(2);c.workspace().add_to_selection(3);
    check(c.dispatch_action("edit.copy")&&c.dispatch_action("edit.paste"),c.status().text);coherent(c.workspace().document());auto copied=*c.workspace().selected_object();check(nurbs_seam_network_ids(c.workspace().document(),copied).size()==3,"Pasted complete network");check(c.dispatch_action("edit.undo")&&c.workspace().document().objects().size()==3,"Paste undo removes complete network");check(c.dispatch_action("edit.redo"),"Paste redo");coherent(c.workspace().document());
    c.workspace().select_object(1);c.workspace().add_to_selection(2);c.workspace().add_to_selection(3);check(c.dispatch_action("edit.duplicate"),c.status().text);coherent(c.workspace().document());check(c.workspace().document().objects().size()==9,"Duplicate adds three coherent patches");check(c.dispatch_action("edit.undo"),"Duplicate undo");coherent(c.workspace().document());
}
void prefabs(){EditorDocument d("Prefab source");fixture(d);const auto dir=std::filesystem::temp_directory_path()/"dve_nurbs_reuse_test";std::filesystem::remove_all(dir);std::filesystem::create_directories(dir);auto partial=capture_editor_prefab(d,std::vector<EditorObjectId>{1},dir/"partial.dveprefab","Partial");check(!partial.success,"Partial prefab capture refuses");auto saved=capture_editor_prefab(d,std::vector<EditorObjectId>{1,2,3},dir/"network.dveprefab","Network");check(saved.success,saved.error);std::string error;auto prefab=load_editor_prefab(dir/"network.dveprefab",&error);check(bool(prefab),error);coherent(prefab->templateDocument);
    EditorDocument scene("Instances");auto pose=make_rigid_transform({3,4,5},quaternion_from_axis_angle({0,1,0},.3F));auto a=instantiate_editor_prefab(scene,*prefab,pose);check(a.success,a.error);auto b=instantiate_editor_prefab(scene,*prefab,make_rigid_transform({-3,1,2},{}));check(b.success,b.error);coherent(scene);check(nurbs_seam_network_ids(scene,a.objectIds.front()).size()==3&&nurbs_seam_network_ids(scene,b.objectIds.front()).size()==3,"Instances keep separate remapped networks");
    auto source=*editor_nurbs_source(*scene.find_object(a.objectIds.front())),after=source;after.controls[7].y+=.1;check(!edit_nurbs_seam_command(a.objectIds.front(),source,after)->execute(scene).success,"Prefab geometry requires detach before editing");
    auto sceneSave=scene.save_transactional(dir/"instances.dvescene");check(sceneSave.success,sceneSave.error);auto loaded=EditorDocument::load(dir/"instances.dvescene",&error);check(bool(loaded),error);coherent(*loaded);
    // Source update must preserve instance identity while remapping every seam.
    prefab->contentHash+=1;auto update=apply_editor_prefab_instance_update(scene,a.instanceId,*prefab,false);check(update.success,update.error);coherent(scene);std::filesystem::remove_all(dir);
}
}
int main(){try{commands();native();prefabs();std::cout<<"NURBS network reuse tests passed\n";return 0;}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
